it('未交运：真实核实→失败不回补→同业务新键重试→只回补一次，旧失败键保持原结果',async()=>{
 const f=await paid(),a=await apply(f);await review(a.afterSaleId,'APPROVE');await physical(f,a.afterSaleId);await saleTask(a.afterSaleId,'REFUND_PROCESS');const b=await refundBody(a.afterSaleId);simulator.mode='FAIL_ONCE';const failed=await refunds().execute(support,a.afterSaleId,b);expect(failed).toMatchObject({attemptOutcome:'FAILED',refundStatus:'FAILED'});expect(await db.inventoryBalance.findUnique({where:{skuId:f.sku.id}})).toMatchObject({available:8,reserved:0});expect(await db.refundAttempt.count({where:{refundId:failed.refundId}})).toBe(1);
 await saleTask(a.afterSaleId,'REFUND_PROCESS');const success=await refunds().execute(support,a.afterSaleId,{...await refundBody(a.afterSaleId),refundId:failed.refundId,expectedRefundVersion:failed.refundVersion},true);expect(success.attemptOutcome).toBe('SUCCEEDED');expect(await db.inventoryBalance.findUnique({where:{skuId:f.sku.id}})).toMatchObject({available:10,reserved:0});expect(await db.order.findUnique({where:{id:f.id}})).toMatchObject({status:'REFUNDED'});expect(await refunds().execute(support,a.afterSaleId,b)).toMatchObject({attemptOutcome:'FAILED',refundStatus:'SUCCEEDED',replayed:true});expect(await db.refund.count({where:{orderId:f.id}})).toBe(1);expect(await db.refundAttempt.count({where:{refundId:failed.refundId}})).toBe(2);expect(await db.inventoryAction.count({where:{actionKey:'RESTOCK_UNSHIPPED_REFUND:'+failed.refundId}})).toBe(1);
});
it('退货：真实交运→无物流实收→草稿→最终验收回补→退款失败不撤回→重试无第二次回补',async()=>{
 const f=await shipped(),a=await apply(f,'RETURN_REFUND');await review(a.afterSaleId,'APPROVE');const r=await receive(a.afterSaleId);await draft(a.afterSaleId,r);await inspect().final(warehouse,a.afterSaleId,{...await settlementBody(a.afterSaleId,'RETURN_INSPECT'),...await refs(a.afterSaleId)});expect(await db.inventoryBalance.findUnique({where:{skuId:f.sku.id}})).toMatchObject({available:10});await saleTask(a.afterSaleId,'REFUND_PROCESS');simulator.mode='FAIL_ONCE';const result=await refunds().execute(support,a.afterSaleId,await refundBody(a.afterSaleId));expect(result.attemptOutcome).toBe('FAILED');expect(await db.inventoryBalance.findUnique({where:{skuId:f.sku.id}})).toMatchObject({available:10});await expect(sales().close(admin,a.afterSaleId,{...await saleBody(a.afterSaleId),reason:'不得关闭',publicExplanation:'不应成功'})).rejects.toMatchObject({code:'AFTER_SALE_CLOSE_FORBIDDEN'});await refunds().execute(support,a.afterSaleId,{...await refundBody(a.afterSaleId),refundId:result.refundId,expectedRefundVersion:result.refundVersion},true);expect(await db.inventoryAction.count({where:{actionKey:'RESTOCK_FINAL_INSPECTION:'+a.afterSaleId}})).toBe(1);expect(await db.inventoryBalance.findUnique({where:{skuId:f.sku.id}})).toMatchObject({available:10});
});
it('同键100并发只有一次成功、一次Attempt；异键同版本失败只执行一次，不串行重试',async()=>{
 const f=await paid(),a=await apply(f);await review(a.afterSaleId,'APPROVE');await physical(f,a.afterSaleId);await saleTask(a.afterSaleId,'REFUND_PROCESS');const b=await refundBody(a.afterSaleId),pending=await Promise.allSettled(Array.from({length:100},()=>refunds().execute(support,a.afterSaleId,b)));for(const r of pending)if(r.status==='rejected')expect(r.reason).toMatchObject({code:'REQUEST_IN_PROGRESS'});const rs=[];for(const r of pending)rs.push(r.status==='fulfilled'?r.value:await refunds().execute(support,a.afterSaleId,b));expect(new Set(rs.map(r=>r.attemptId)).size).toBe(1);expect(await db.refundAttempt.count({where:{refundId:rs[0]!.refundId}})).toBe(1);
 const g=await paid(),ag=await apply(g);await review(ag.afterSaleId,'APPROVE');await physical(g,ag.afterSaleId);await saleTask(ag.afterSaleId,'REFUND_PROCESS');const bg=await refundBody(ag.afterSaleId);simulator.mode='ALWAYS_FAIL';const failures=await Promise.allSettled(Array.from({length:100},()=>refunds().execute(support,ag.afterSaleId,{...bg,commandKey:randomUUID()})));expect(failures.filter(r=>r.status==='fulfilled')).toHaveLength(1);expect(await db.refundAttempt.count({where:{refundId:(await db.refund.findUniqueOrThrow({where:{afterSaleId:ag.afterSaleId}})).id}})).toBe(1);
},60000);
