function deferred(){let resolve!:()=>void;const promise=new Promise<void>(r=>{resolve=r;});return {resolve,promise};}
it.each(['loss-first','refund-first'] as const)('真实锁竞争 %s：锁后重判，损耗先拒绝退款，退款先将后续损耗扣A',async first=>{
 const f=await paid(),a=await apply(f);await review(a.afterSaleId,'APPROVE');await physical(f,a.afterSaleId);await saleTask(a.afterSaleId,'REFUND_PROCESS');const b=await refundBody(a.afterSaleId),item=await db.orderItem.findFirstOrThrow({where:{orderId:f.id}}),gate=deferred(),release=deferred();
 audit.barrier={matches:p=>first==='loss-first'?p.action==='stock.incident':p.action==='after-sale.change',entered:()=>gate.resolve(),release:release.promise};
 const loss=()=>app.get(StockIncidents).create(warehouse,{incidentKey:randomUUID(),skuId:f.sku.id,reason:'并发真实发现一件损耗',evidenceNote:'独占锁屏障',items:[{orderItemId:item.id,damagedQuantity:1}],evidenceFileIds:[]}),refund=()=>refunds().execute(support,a.afterSaleId,b);
 const winner=first==='loss-first'?loss():refund();await gate.promise;const loser=(first==='loss-first'?refund():loss()).then(value=>({ok:true,value}),error=>({ok:false,error}));release.resolve();await winner;const outcome=await loser;if(first==='loss-first'){expect(outcome).toMatchObject({ok:false,error:{code:'PHYSICAL_CHECK_STALE'}});expect(await db.refundAttempt.count({where:{physicalCheckId:b.physicalCheckId}})).toBe(0);expect(await db.inventoryBalance.findUnique({where:{skuId:f.sku.id}})).toMatchObject({available:8});}else{expect(outcome.ok).toBe(true);expect(await db.inventoryBalance.findUnique({where:{skuId:f.sku.id}})).toMatchObject({available:9});expect(await db.inventoryLedger.findFirst({where:{businessId:f.id,eventType:'AVAILABLE_LOSS'}})).toMatchObject({deltaA:-1});}
});

