 const f=await paid(),a=await apply(f);await review(a.afterSaleId,'APPROVE');await physical(f,a.afterSaleId);await saleTask(a.afterSaleId,'REFUND_PROCESS');const b=await refundBody(a.afterSaleId),path='/admin/after-sales/'+a.afterSaleId,task=await db.task.findFirstOrThrow({where:{businessId:a.afterSaleId,stage:'REFUND_PROCESS'}});simulator.mode='FAIL_ONCE';
 const first=await http('POST',path+'/refund',support,b);expect(first).toMatchObject({status:200,json:{data:{attemptOutcome:'FAILED',refundStatus:'FAILED',status:'REFUND_FAILED'}}});expect(await db.inventoryBalance.findUnique({where:{skuId:f.sku.id}})).toMatchObject({available:8});expect(await db.task.findUnique({where:{id:task.id}})).toMatchObject({round:task.round,dueAt:task.dueAt,status:'CLAIMED'});
 const retry=await http('POST',path+'/refund-retries',support,{...await refundBody(a.afterSaleId),refundId:first.json.data.refundId,expectedRefundVersion:first.json.data.refundVersion});expect(retry).toMatchObject({status:200,json:{data:{refundId:first.json.data.refundId,attemptOutcome:'SUCCEEDED'}}});expect(await http('POST',path+'/refund',support,b)).toMatchObject({status:200,json:{data:{attemptId:first.json.data.attemptId,attemptOutcome:'FAILED',refundStatus:'SUCCEEDED',retryAllowed:false}}});expect(await db.inventoryBalance.findUnique({where:{skuId:f.sku.id}})).toMatchObject({available:10});
